#!/nix/store/3n4qphl9s728sz8frmpqqrv9b1m87g68-python3-3.14.7/bin/python
import sqlite3
import sys
import time

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"
POLL_SECONDS = 0.2


def open_db():
    connection = sqlite3.connect(DB_PATH, timeout=30.0)
    connection.execute("PRAGMA busy_timeout=30000")
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA synchronous=FULL")
    return connection


def process_one(connection):
    connection.execute("BEGIN IMMEDIATE")
    row = connection.execute(
        "SELECT id, payload, status FROM jobs "
        "WHERE status IN ('queued', 'processing') "
        "ORDER BY rowid LIMIT 1"
    ).fetchone()
    if row is None:
        connection.rollback()
        return False

    job_id, payload, status = row
    result = "processed:" + payload
    connection.execute(
        "UPDATE jobs SET status='completed', result=?, attempts=1 "
        "WHERE id=? AND status=?",
        (result, job_id, status),
    )
    connection.commit()
    return True


def run():
    connection = open_db()
    try:
        while True:
            try:
                if not process_one(connection):
                    time.sleep(POLL_SECONDS)
            except sqlite3.OperationalError:
                if connection.in_transaction:
                    connection.rollback()
                time.sleep(POLL_SECONDS)
            except Exception as error:
                if connection.in_transaction:
                    connection.rollback()
                print(f"queue worker error: {error}", file=sys.stderr, flush=True)
                time.sleep(POLL_SECONDS)
    finally:
        connection.close()


if __name__ == "__main__":
    run()

